--
-- Table structure for table `md_exchange_rate`
--

DROP TABLE IF EXISTS `md_exchange_rate`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `md_exchange_rate` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `from_currency` varchar(10) NOT NULL COMMENT '源币种',
  `to_currency` varchar(10) NOT NULL COMMENT '目标币种(一般为本位币)',
  `rate_type` varchar(20) NOT NULL DEFAULT 'MIDDLE' COMMENT '汇率类型:MIDDLE中间价/BUY买入价/SELL卖出价',
  `rate` decimal(20,10) NOT NULL COMMENT '汇率',
  `effect_date` date NOT NULL COMMENT '生效日期',
  `expire_date` date DEFAULT NULL COMMENT '失效日期,空表示长期有效',
  `source` varchar(20) NOT NULL DEFAULT 'MANUAL' COMMENT '来源:MANUAL手工/API接口',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tenant_rate` (`tenant_id`,`from_currency`,`to_currency`,`rate_type`,`effect_date`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_date` (`tenant_id`,`effect_date`)
) ENGINE=InnoDB AUTO_INCREMENT=106 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='汇率';
